/*
 * GP Refresh — integration settings shared by the landing page, thank-you page and prospectus access page.
 *
 * Everything here is public: it ships to every visitor's browser. Never put a GHL API key,
 * private integration token, access code, or prospectus file URL in this file.
 * Prospectus access codes live in js/gpr-access-codes.js, generated by make-access-codes.js.
 * See README.md › "GHL integration" for how to fill these in.
 */
window.GPR_CONFIG = {
	eoi: {
		// Option A (preferred): the GHL form's embed URL, e.g. "https://api.leadconnectorhq.com/widget/form/<FORM_ID>".
		// When set, the GHL-hosted form replaces the on-page form. Set "On Submit → Display Message" in the
		// GHL form builder so GHL shows the thank-you message in place of its form.
		ghlFormEmbedUrl: "",
		// Option B: an endpoint that receives the on-page form as JSON, such as a GHL workflow
		// "Inbound Webhook" trigger URL. It must allow CORS from the site's origin and return a 2xx status;
		// the form is replaced by the thank-you message only when that response is received.
		submitUrl: ""
	},
	landingUrl: "our-world.html",
	eoiUrl: "our-world.html#expression-of-interest",
	accessUrl: "prospectus-access.html",
	contact: { email: "connect@gprefresh.com", phone: "1300 477 337" }
};
